package org.slavicmyths.hunt;

import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.effect.*;
import net.minecraft.world.phys.Vec3;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.core.BlockPos;
import net.neoforged.neoforge.gametest.*;
import org.slavicmyths.registry.ModEntities;
import static org.slavicmyths.hunt.BossRules.Move;

@GameTestHolder("slavicmyths_tugarin") @PrefixGameTestTemplate(false)
public final class BossReimplementationGameTests {
    private static final class Connection extends net.minecraft.network.Connection {
        private final io.netty.channel.embedded.EmbeddedChannel channel=new io.netty.channel.embedded.EmbeddedChannel();
        Connection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}
        @Override public io.netty.channel.Channel channel(){return channel;}
    }
    private static final class Listener extends net.minecraft.server.network.ServerGamePacketListenerImpl {
        Listener(net.minecraft.server.level.ServerPlayer p){super(p.getServer(),new Connection(),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));}
        @Override public void send(net.minecraft.network.protocol.Packet<?> packet) { }
        @Override public void send(net.minecraft.network.protocol.Packet<?> packet,net.minecraft.network.PacketSendListener listener) { }
    }
    private static net.minecraft.server.level.ServerPlayer player(GameTestHelper t){var p=new net.minecraft.server.level.ServerPlayer(t.getLevel().getServer(),t.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"RareProbe"),net.minecraft.server.level.ClientInformation.createDefault());p.connection=new Listener(p);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.moveTo(t.absoluteVec(new Vec3(3,2,3)));p.setNoGravity(true);for(int i=0;i<61;i++)p.tick();return p;}
    private static WorldBoss boss(GameTestHelper t){WorldBoss b=ModEntities.TUGARIN_ZMEY.get().create(t.getLevel());b.moveTo(t.absoluteVec(new Vec3(4,2,4)));b.setNoAi(true);b.setNoGravity(true);t.getLevel().addFreshEntity(b);return b;}
    private static net.minecraft.world.entity.animal.Cow target(GameTestHelper t,WorldBoss b,double range){var e=EntityType.COW.create(t.getLevel());e.moveTo(b.position().add(0,0,range));e.setNoAi(true);e.setNoGravity(true);e.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);e.setHealth(100);t.getLevel().addFreshEntity(e);b.setTarget(e);return e;}
    private static TugarinCombat combat(WorldBoss b){try{var f=WorldBoss.class.getDeclaredMethod("tugarin");f.setAccessible(true);return (TugarinCombat)f.invoke(b);}catch(Exception e){throw new AssertionError(e);}}
    private static void ticks(WorldBoss b,int ticks){for(int i=0;i<ticks;i++){b.tickCount++;combat(b).tick();}}
    private static void begin(WorldBoss b,Move m,LivingEntity e){try{var f=TugarinCombat.class.getDeclaredMethod("begin",Move.class,LivingEntity.class);f.setAccessible(true);f.invoke(combat(b),m,e);}catch(Exception ex){throw new AssertionError(ex);}}

    private static void diamond(net.minecraft.server.level.ServerPlayer p){p.setItemSlot(EquipmentSlot.HEAD,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND_HELMET));p.setItemSlot(EquipmentSlot.CHEST,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND_CHESTPLATE));p.setItemSlot(EquipmentSlot.LEGS,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND_LEGGINGS));p.setItemSlot(EquipmentSlot.FEET,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND_BOOTS));p.doTick();}
    private static void tugarinDiamond(GameTestHelper t,boolean phase2){var b=boss(t);var p=player(t);diamond(p);p.moveTo(b.position().add(0,0,2));if(phase2)b.tugarinState(WorldBoss.TugarinState.PHASE_TWO);b.setTarget(p);ticks(b,1);begin(b,Move.PUNCH,p);ticks(b,10);float damage=20-p.getHealth();System.out.println("DIAMOND TUGARIN "+phase2+" damage="+damage);t.assertTrue(p.getArmorValue()==20&&Math.abs(p.getAttributeValue(Attributes.ARMOR_TOUGHNESS)-8)<.001,"not real full diamond armor");t.assertTrue(damage>=3&&damage<5,"single native melee diamond damage "+damage);t.succeed();}
    @GameTest(template="empty") public static void tugarinDiamondPhaseOne(GameTestHelper t){tugarinDiamond(t,false);}
    @GameTest(template="empty") public static void tugarinDiamondPhaseTwo(GameTestHelper t){tugarinDiamond(t,true);}
    private static org.slavicmyths.bandit.NightingaleEntity nightingale(GameTestHelper t){var b=ModEntities.NIGHTINGALE.get().create(t.getLevel());b.moveTo(t.absoluteVec(new Vec3(4,2,4)));b.setNoAi(true);b.setNoGravity(true);t.getLevel().addFreshEntity(b);return b;}
    private static void start(org.slavicmyths.bandit.NightingaleEntity b,int action,int ticks){try{var m=b.getClass().getDeclaredMethod("startAttack",int.class,int.class,int.class);m.setAccessible(true);m.invoke(b,action,ticks,200);}catch(Exception e){throw new AssertionError(e);}}
    private static void nightTicks(org.slavicmyths.bandit.NightingaleEntity b,int count){for(int i=0;i<count;i++){b.tickCount++;b.aiStep();}}
    private static void nightDiamond(GameTestHelper t,boolean phase2){var b=nightingale(t);var p=player(t);diamond(p);p.moveTo(b.position().add(0,0,2));b.setTarget(p);if(phase2){b.setHealth(125);nightTicks(b,40);}start(b,b.QUICK,20);nightTicks(b,10);float damage=20-p.getHealth();System.out.println("DIAMOND NIGHTINGALE "+phase2+" damage="+damage);t.assertTrue(p.getArmorValue()==20&&p.getAttributeValue(Attributes.ARMOR_TOUGHNESS)==8,"not full diamond");t.assertTrue(damage>=3&&damage<5,"native ordinary melee damage "+damage);t.succeed();}
    @GameTest(template="empty") public static void nightingaleDiamondPhaseOne(GameTestHelper t){nightDiamond(t,false);}
    @GameTest(template="empty") public static void nightingaleDiamondPhaseTwo(GameTestHelper t){nightDiamond(t,true);}
    @GameTest(template="empty") public static void nightingalePhasePersists(GameTestHelper t){var b=nightingale(t);var id=b.getUUID();b.setHealth(126);nightTicks(b,1);t.assertTrue(b.phase()==org.slavicmyths.bandit.NightingaleEntity.Phase.PHASE_ONE,"early phase");b.setHealth(125);nightTicks(b,1);t.assertTrue(b.phase()==org.slavicmyths.bandit.NightingaleEntity.Phase.TRANSFORMING,"missing transition");var n=new CompoundTag();b.saveWithoutId(n);var loaded=nightingale(t);loaded.load(n);t.assertTrue(loaded.phase()==org.slavicmyths.bandit.NightingaleEntity.Phase.PHASE_TWO&&loaded.getHealth()==125&&loaded.getUUID().equals(id),"saved transition replay/heal/UUID");loaded.setHealth(240);nightTicks(loaded,50);t.assertTrue(loaded.phase()==org.slavicmyths.bandit.NightingaleEntity.Phase.PHASE_TWO,"phase regression");t.succeed();}
    @GameTest(template="empty") public static void nativeCommandsAndEgg(GameTestHelper t){var p=player(t);var source=p.createCommandSourceStack().withPermission(4);var commands=t.getLevel().getServer().getCommands();for(String c:List.of("summon slavicmyths:tugarin_zmey ~ ~ ~","summon slavicmyths:nightingale ~ ~ ~","give @s slavicmyths:nightingale_spawn_egg","give @s slavicmyths:nightingale_dagger")){int[] result={0};commands.performPrefixedCommand(source.withCallback((success,value)->{if(success)result[0]=value;}),c);t.assertTrue(result[0]>0,"actual command failed: "+c);}t.assertTrue(((net.minecraft.world.item.SpawnEggItem)org.slavicmyths.registry.ModItems.NIGHTINGALE_SPAWN_EGG.get()).getType(new net.minecraft.world.item.ItemStack(org.slavicmyths.registry.ModItems.NIGHTINGALE_SPAWN_EGG.get()))==ModEntities.NIGHTINGALE.get(),"egg wrong entity");t.assertTrue(org.slavicmyths.registry.ModItemGroup.items(8).stream().anyMatch(i->i==org.slavicmyths.registry.ModItems.NIGHTINGALE_SPAWN_EGG.get()),"egg creative missing");t.succeed();}
    @GameTest(template="empty") public static void highResistanceWindAtSevenBlocks(GameTestHelper t){var p=player(t);var b=boss(t);b.moveTo(p.position().add(0,0,7.5));p.setYRot(0);float hp=b.getHealth();org.slavicmyths.bandit.WindAttack.bladeWave(p,new Vec3(0,0,1));t.assertTrue(b.getHealth()<hp,"boss immune or range <7.5");t.assertTrue(b.getDeltaMovement().z>=.49,"wind minimum impulse absent");Vec3 old=b.position();b.move(MoverType.SELF,b.getDeltaMovement());t.assertTrue(b.getZ()-old.z>=.35,"wind has no real displacement");System.out.println("WIND boss displacement="+(b.getZ()-old.z));t.succeed();}
    @GameTest(template="empty") public static void whistleDamageAndVelocityAtSix(GameTestHelper t){var b=nightingale(t);var p=player(t);p.moveTo(b.position().add(0,0,6));t.getLevel().addNewPlayer(p);b.setTarget(p);start(b,b.INHALE,28);nightTicks(b,16);t.assertTrue(p.getHealth()<20&&p.getDeltaMovement().z>=.35,"6-block whistle health/velocity");t.succeed();}
    @GameTest(template="empty",timeoutTicks=120) public static void tugarinAttacksVillager(GameTestHelper t){var b=boss(t);b.setNoAi(false);var v=EntityType.VILLAGER.create(t.getLevel());v.moveTo(b.position().add(0,0,2));v.setNoAi(true);v.setNoGravity(true);v.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);v.setHealth(200);t.getLevel().addFreshEntity(v);t.runAfterDelay(70,()->{t.assertTrue(b.getTarget()==v&&v.getHealth()<200,"Tugarin ignored nearby villager");t.succeed();});}
    @GameTest(template="empty",timeoutTicks=120) public static void nightingaleAttacksVillager(GameTestHelper t){var b=nightingale(t);b.setNoAi(false);var v=EntityType.VILLAGER.create(t.getLevel());v.moveTo(b.position().add(0,0,2));v.setNoAi(true);v.setNoGravity(true);v.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);v.setHealth(200);t.getLevel().addFreshEntity(v);t.runAfterDelay(70,()->{t.assertTrue(b.getTarget()==v&&v.getHealth()<200,"Nightingale ignored nearby villager");t.succeed();});}
    @GameTest(template="empty") public static void requiredSoundRegistry(GameTestHelper t){var profiles=org.slavicmyths.registry.ModSounds.BOSS_REIMPLEMENTATION_PROFILES;t.assertTrue(profiles.size()==39,"required sound count");for(var e:profiles.entrySet())t.assertTrue(net.minecraft.core.registries.BuiltInRegistries.SOUND_EVENT.getKey(e.getValue().get()).getPath().equals(e.getKey()),"missing sound "+e.getKey());t.succeed();}
    @GameTest(template="empty",timeoutTicks=120) public static void villagerFearAndGolemThreat(GameTestHelper t){var b=boss(t);var v=EntityType.VILLAGER.create(t.getLevel());v.moveTo(b.position().add(0,0,3));v.setNoGravity(true);t.getLevel().addFreshEntity(v);var g=EntityType.IRON_GOLEM.create(t.getLevel());g.moveTo(b.position().add(3,0,0));g.setNoGravity(true);t.getLevel().addFreshEntity(g);t.runAfterDelay(40,()->{t.assertTrue(v.getBrain().getMemory(net.minecraft.world.entity.ai.memory.MemoryModuleType.NEAREST_HOSTILE).orElse(null)==b,"native villager hostile sensor missing Tugarin");t.assertTrue(g.getTarget()==b,"native golem goal ignored Tugarin");t.succeed();});}
    @GameTest(template="empty",timeoutTicks=120) public static void nightingaleFearAndGolemThreat(GameTestHelper t){var b=nightingale(t);var v=EntityType.VILLAGER.create(t.getLevel());v.moveTo(b.position().add(0,0,4));v.setNoGravity(true);v.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);v.setHealth(200);t.getLevel().addFreshEntity(v);var g=EntityType.IRON_GOLEM.create(t.getLevel());g.moveTo(b.position().add(3,0,0));g.setNoGravity(true);t.getLevel().addFreshEntity(g);t.runAfterDelay(40,()->{t.assertTrue(v.getBrain().getMemory(net.minecraft.world.entity.ai.memory.MemoryModuleType.NEAREST_HOSTILE).orElse(null)==b,"native villager hostile sensor missing Nightingale");t.assertTrue(g.getTarget()==b,"native golem goal ignored Nightingale");t.succeed();});}

    @GameTest(template="empty") public static void nightingaleNativeWeaknessOnce(GameTestHelper t){var b=nightingale(t);var p=player(t);p.moveTo(b.position().add(0,0,2));b.setTarget(p);b.addEffect(new MobEffectInstance(MobEffects.WEAKNESS,200));start(b,b.QUICK,20);nightTicks(b,10);t.assertTrue(Math.abs(20-p.getHealth()-6)<.001,"Weakness must subtract four exactly once");t.succeed();}
    @GameTest(template="empty") public static void bladeWaveRangeAndWidth(GameTestHelper t){var p=player(t);var b=boss(t);b.moveTo(p.position().add(0,0,9));float hp=b.getHealth();org.slavicmyths.bandit.WindAttack.bladeWave(p,new Vec3(0,0,1));t.assertTrue(b.getHealth()==hp,"wave exceeded 8 blocks");b.moveTo(p.position().add(4,0,5));org.slavicmyths.bandit.WindAttack.bladeWave(p,new Vec3(0,0,1));t.assertTrue(b.getHealth()==hp,"wave exceeded fixed width");t.succeed();}

    @GameTest(template="empty",timeoutTicks=80) public static void nightingaleLeapDamagesOnLanding(GameTestHelper t){var b=nightingale(t);b.setNoAi(false);b.setNoGravity(false);var cow=EntityType.COW.create(t.getLevel());cow.moveTo(b.position().add(0,0,5.5));cow.setNoAi(true);cow.setNoGravity(true);cow.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);cow.setHealth(100);t.getLevel().addFreshEntity(cow);b.hurt(b.damageSources().mobAttack(cow),1);b.setTarget(cow);for(int x=2;x<=6;x++)for(int z=2;z<=13;z++)t.setBlock(new BlockPos(x,1,z),net.minecraft.world.level.block.Blocks.STONE);start(b,b.LEAP_ATTACK,36);t.runAfterDelay(32,()->{t.assertTrue(b.onGround(),"leap has not landed");System.out.println("LEAP actual distance="+b.distanceTo(cow)+" HP="+cow.getHealth());t.assertTrue(cow.getHealth()==88,"landing AoE raw damage should be 12 exactly once, actual HP "+cow.getHealth());t.succeed();});}

    private static void onslaught(GameTestHelper t,boolean escape){var b=nightingale(t);b.setNoAi(false);var n=new CompoundTag();b.saveWithoutId(n);n.putString("NightingalePhase","PHASE_TWO");b.load(n);var cow=EntityType.COW.create(t.getLevel());cow.moveTo(b.position().add(0,0,5.5));cow.setNoAi(true);cow.setNoGravity(true);cow.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);cow.setHealth(100);t.getLevel().addFreshEntity(cow);b.setTarget(cow);start(b,b.ONSLAUGHT,52);if(escape)t.runAfterDelay(19,()->cow.moveTo(cow.position().add(20,0,0)));t.runAfterDelay(50,()->{System.out.println("ONSLAUGHT escape="+escape+" HP="+cow.getHealth()+" distance="+b.distanceTo(cow));t.assertTrue(Math.abs(cow.getHealth()-(escape?100:82))<.001,"onslaught combo/escape damage "+cow.getHealth());t.succeed();});}
    @GameTest(template="empty",timeoutTicks=80) public static void onslaughtHitsAfterPassingTarget(GameTestHelper t){onslaught(t,false);}
    @GameTest(template="empty",timeoutTicks=80) public static void onslaughtCanBeEscaped(GameTestHelper t){onslaught(t,true);}

    @GameTest(template="empty") public static void explicitWindImmunityTag(GameTestHelper t){var b=nightingale(t);var pig=EntityType.PIG.create(t.getLevel());pig.moveTo(b.position().add(0,0,3));pig.setNoAi(true);pig.setNoGravity(true);t.getLevel().addFreshEntity(pig);t.assertTrue(pig.getType().is(org.slavicmyths.bandit.WindImpulse.IMMUNE),"test datapack wind immunity tag missing");org.slavicmyths.bandit.WindAttack.release(b,new Vec3(0,0,1),8,14,2,false,false);t.assertTrue(pig.getHealth()==10&&pig.getDeltaMovement().lengthSqr()==0,"explicit wind immunity ignored");t.succeed();}

}
